import type { CycleSummary, DebtRow, Direction, InstallmentRow, PaymentRow } from './schemas';

export interface DebtDetail {
  debt: DebtRow;
  memo: string | null;
  category: string | null;
  payments: PaymentRow[];
  installments: InstallmentRow[];
}

/** A payment to record. `id` is generated by the client and reused on retry (idempotency key). */
export interface NewPayment {
  id: string;
  debtId: string;
  paidOn: string;
  amountIdr: number;
  reference: string | null;
  note: string | null;
}

/** A reversal entry: written as a NEW negative ledger row that points at the payment it cancels. */
export interface NewReversal {
  id: string;
  debtId: string;
  reversesPaymentId: string;
  /** The original payment's (positive) amount; the entry is stored as its exact negative. */
  amountIdr: number;
  paidOn: string;
  note: string | null;
}

/** A new record with its full installment schedule, created atomically by the create_debt RPC. */
export interface NewDebt {
  /** Generated by the client when the form opens and reused on every retry (idempotency key). */
  id: string;
  direction: Direction;
  name: string;
  totalIdr: number;
  installments: Array<{ dueDate: string; amountIdr: number }>;
  description: string | null;
  category: string | null;
  memo: string | null;
}

/** The text of a record. Amounts and schedule cannot be changed once it exists (database column grants). */
export interface DebtDetailsUpdate {
  name: string;
  description: string | null;
  category: string | null;
  memo: string | null;
}

/** Per-book settings the owner can change (DESIGN.md section 7.7, "Gajian"). */
export interface BookSettings {
  name: string;
  paydayDay: number;
  /** null = not used: the cycle card then shows "Kewajiban siklus" instead of "Sisa kas setelah cicilan". */
  baseSalaryIdr: number | null;
}

export interface BookSettingsUpdate {
  paydayDay: number;
  baseSalaryIdr: number | null;
}

export class NotFoundError extends Error {
  constructor(what: string) {
    super(`NOT_FOUND: ${what}`);
    this.name = 'NotFoundError';
  }
}

/**
 * Satu-satunya pintu data untuk UI. Perhitungan (status, siklus, sisa) berasal dari SQL
 * (`debt_list`, `cycle_summary`); implementasi hanya mengambil dan memvalidasi.
 * Dua implementasi: fixture (dibangkitkan dari SQL asli; hanya mode `--mode fixture`) dan Supabase.
 */
export interface DataSource {
  readonly kind: 'fixture' | 'supabase';
  /** The active book. Every number on one screen comes from a single book. */
  readonly bookId: string;
  /** Tanggal hari ini (ISO) menurut zona waktu buku. */
  getToday(): string;
  cycleSummary(): Promise<CycleSummary>;
  debts(): Promise<DebtRow[]>;
  debtDetail(debtId: string): Promise<DebtDetail>;
  inboxPendingCount(): Promise<number>;
  /** Appends a payment to the ledger. Throws PaymentWriteError. Ledger rows are never updated or deleted. */
  recordPayment(payment: NewPayment): Promise<void>;
  /** Appends a reversal entry. Throws PaymentWriteError. */
  reversePayment(reversal: NewReversal): Promise<void>;
  /** Creates a record and its installments in one transaction. Idempotent per id. Throws DebtWriteError. */
  createDebt(debt: NewDebt): Promise<void>;
  /** Updates the text of a record. Throws DebtWriteError. */
  updateDebtDetails(debtId: string, update: DebtDetailsUpdate): Promise<void>;
  /** Deletes a record that has no payments (its installments go with it). Throws DebtWriteError ('has_payments'). */
  deleteDebt(debtId: string): Promise<void>;
  /** Installments due between two dates (inclusive), for the calendar. Same rows as installment_status. */
  installmentsBetween(from: string, to: string): Promise<InstallmentRow[]>;
  bookSettings(): Promise<BookSettings>;
  /** Sets the payday and base salary of the active book. Idempotent. Throws SettingsWriteError. */
  updateBookSettings(update: BookSettingsUpdate): Promise<void>;
}
